/* 학습 해설
 * Frequency QoS 핸들: 등록 성공0과 요청 제거 후 초기화
 * 주파수 요청은 등록한 객체를 나중에 수정·제거하는 방식입니다. 반환0을 실패로 오해하거나 제거 전 객체를 재사용하면 목록과 소유권 관리가 깨질 수 있습니다.
 * add는 qos·req·값을 검사하고 이미 active이면 경고와 EINVAL입니다. req에 qos와 type을 기록한 뒤 apply합니다. 음수이면 두 필드를NULL·0으로 되돌립니다. 반환0은 집계값이 그대로인 등록 성공이며1은 집계 변화입니다. 헤더의 active는 req->qos가NULL 또는 오류 포인터가 아닌지로 판단합니다.
 * 기존 최소 요구1200에 새 요구800을 추가하면 등록은 되지만 유효 값1200 그대로라0일 수 있습니다. 이후1200 요청을 제거하면800이 영향을 줍니다. 처음의0을 실패로 보고800 요청 객체를 즉시 해제하면 여전히 목록에서 참조하는 객체를 잃습니다. 요청 객체는 등록 동안 안정적으로 유지하고 제거 API 뒤에 수명을 끝내야 합니다.
 */
int freq_qos_add_request(struct freq_constraints *qos,
			 struct freq_qos_request *req,
			 enum freq_qos_req_type type, s32 value)
{
	int ret;

	if (IS_ERR_OR_NULL(qos) || !req || freq_qos_value_invalid(value))
		return -EINVAL;

	if (WARN(freq_qos_request_active(req),
		 "%s() called for active request\n", __func__))
		return -EINVAL;

	req->qos = qos;
	req->type = type;
	ret = freq_qos_apply(req, PM_QOS_ADD_REQ, value);
	if (ret < 0) {
		req->qos = NULL;
		req->type = 0;
	}

	return ret;
}
EXPORT_SYMBOL_GPL(freq_qos_add_request);

/**
 * freq_qos_update_request - Modify existing frequency QoS request.
 * @req: Request to modify.
 * @new_value: New request value.
 *
 * Update an existing frequency QoS request along with the effective constraint
 * value for the list of requests it belongs to.
 *
 * Return 1 if the effective constraint value has changed, 0 if the effective
 * constraint value has not changed, or a negative error code on failures.
 */

