/* 학습 해설
 * Regcache 초기화: Backend 선택과 기본값 배열의 소유권
 * 장치 레지스터 값을 RAM에 보관하면 느린 버스 접근을 줄이고 전원 복구 때 설정을 다시 쓸 수 있습니다. 캐시 자료구조와 기본값 메모리의 소유권을 명확히 해야 설정 배열이 사라진 뒤 잘못된 포인터를 사용하지 않습니다.
 * init은 REGCACHE_NONE이면 bypass를 켜고0입니다. 캐시를 쓰면 기본값 포인터·개수 쌍과 레지스터 stride 정렬을 검사합니다. rbtree·maple·flat ops 중 type을 찾아 read·write·name이 있는지 확인합니다. word 크기는 val_bits를8로 나눈 올림이고 raw 크기는 word 크기와 raw 개수의 곱입니다. 명시적 reg_defaults는 kmemdup_array로 복사합니다.
 * val_bits=16,raw 항목4개이면 word2바이트,raw8바이트입니다. stride2이면 기본값 주소0·2·4는 정렬됐지만3은 거절됩니다. REGCACHE_NONE 경로는 기본값 설정이 있어도 경고 후 bypass로 끝나며 나머지 검사를 똑같이 수행하는 것은 아닙니다.
 */
int regcache_init(struct regmap *map, const struct regmap_config *config)
{
	int ret;
	int i;
	void *tmp_buf;

	if (map->cache_type == REGCACHE_NONE) {
		if (config->reg_defaults || config->num_reg_defaults_raw)
			dev_warn(map->dev,
				 "No cache used with register defaults set!\n");

		map->cache_bypass = true;
		return 0;
	}

	if (config->reg_defaults && !config->num_reg_defaults) {
		dev_err(map->dev,
			 "Register defaults are set without the number!\n");
		return -EINVAL;
	}

	if (config->num_reg_defaults && !config->reg_defaults) {
		dev_err(map->dev,
			"Register defaults number are set without the reg!\n");
		return -EINVAL;
	}

