/* 학습 해설
 * Regcache HW 기본값 생성: 일괄 읽기 실패 뒤 개별 읽기로 전환
 * 일부 장치는 드라이버가 모든 reset 기본값을 정적으로 제공하지 않습니다. 하드웨어에서 읽어 캐시 초기값을 만들 수 있지만 읽을 수 없거나 자체적으로 바뀌는 레지스터를 같은 방식으로 저장하면 안 됩니다.
 * hw_init은 raw 개수가0이면 EINVAL입니다. readable이면서 nonvolatile인 레지스터만 세고 하나도 없으면 bypass=true로 끝냅니다. 기본값 배열을 할당하고 raw 데이터가 없으면 임시 bypass로 전체 raw read를 시도합니다. 성공하면 raw 버퍼를 저장하고 cache_free=true입니다. 실패하면 임시 버퍼를 해제하고 각 유효 레지스터를 regmap_read하는 경로로 이어집니다.
 * 주소0·2·4·6 중2는 unreadable,4는 volatile이면 기본값 배열에는0과6만 들어갑니다. raw read 실패가 곧 전체 초기화 실패는 아니며 두 레지스터의 개별 읽기가 성공하면 완료할 수 있습니다. 개별 읽기 실패는 해당 오류로 종료하므로 부분적으로 채운 배열을 성공한 캐시로 취급하지 않습니다.
 */
static int regcache_hw_init(struct regmap *map)
{
	int i, j;
	int ret;
	int count;
	unsigned int reg, val;
	void *tmp_buf;

	if (!map->num_reg_defaults_raw)
		return -EINVAL;

	/* calculate the size of reg_defaults */
	for (count = 0, i = 0; i < map->num_reg_defaults_raw; i++)
		if (regmap_readable(map, i * map->reg_stride) &&
		    !regmap_volatile(map, i * map->reg_stride))
			count++;

	/* all registers are unreadable or volatile, so just bypass */
	if (!count) {
		map->cache_bypass = true;
		return 0;
	}

	map->num_reg_defaults = count;
	map->reg_defaults = kmalloc_array(count, sizeof(struct reg_default),
					  GFP_KERNEL);

