/* 학습 해설
 * Regcache Only·Bypass·Dirty: 장치 전원 복구 때 필요한 세 상태
 * 장치 전원을 꺼 두면서 설정 요청을 받아 저장할 때와,저장된 설정을 장치에 실제로 써야 할 때는 반대 경로가 필요합니다. 캐시를 사용할지와 하드웨어가 캐시를 반영했는지를 별도 상태로 관리합니다.
 * cache_only setter는 map 잠금 아래 cache_only를 바꿉니다. 캐시가 있는데 bypass도 켜진 상태에서 enable하면 WARN이지만 대입은 합니다. bypass setter도 cache_only와 동시 enable에 WARN 후 값을 설정합니다. mark_dirty는 cache_dirty=true와 no_sync_defaults=true를 함께 기록해 장치가 reset 기본값으로 돌아갔음을 알립니다.
 * 전원이 꺼진 동안 일반 regmap 쓰기를 cache_only로 받아 RAM에 저장하고,복구 후 cache_only를 해제해 sync로 장치에 반영하는 흐름을 생각할 수 있습니다. 장치가 reset됐다면 mark_dirty로 기본값과 같은 항목은 다시 쓸 필요가 없다는 정보도 제공합니다. bypass는 cache를 직접 갱신하지 않고 hardware로 보내는 목적입니다.
 */
void regcache_mark_dirty(struct regmap *map)
{
	map->lock(map->lock_arg);
	map->cache_dirty = true;
	map->no_sync_defaults = true;
	map->unlock(map->lock_arg);
}
EXPORT_SYMBOL_GPL(regcache_mark_dirty);

/**
 * regcache_cache_bypass - Put a register map into cache bypass mode
 *
 * @map: map to configure
 * @enable: flag if changes should not be written to the cache
 *
 * When a register map is marked with the cache bypass option, writes
 * to the register map API will only update the hardware and not
 * the cache directly.  This is useful when syncing the cache back to
 * the hardware.
 */
void regcache_cache_bypass(struct regmap *map, bool enable)
{
	map->lock(map->lock_arg);
	WARN_ON(map->cache_only && enable);
	map->cache_bypass = enable;
	trace_regmap_cache_bypass(map, enable);

