/* 학습 해설
 * Regcache Raw Batch: 빈 구멍과 기본값에서 묶음을 끊기
 * 연속된 레지스터를 한 번에 쓰면 버스 전송 비용을 줄일 수 있지만 캐시에 없는 항목이나 쓰면 안 되는 항목까지 포함하면 잘못된 설정을 보낼 수 있습니다. 전송 가능한 연속 구간을 만들고 구멍에서 묶음을 끊어야 합니다.
 * sync_block은 raw write가 가능하고 use_single_write가false이면 raw 경로,아니면 single 경로입니다. 두 경로 모두 index start부터end 미만까지 reg=block_base+i*stride로 봅니다. present bitmap이NULL이면 모두 존재한 것으로 보며,아니면 bit를 검사합니다. raw는 absent·비writeable·needs_sync false를 만나면 그 직전까지 쌓은 구간을 flush합니다.
 * stride2에서 주소0·2는 전송 대상,4는 구멍,6은 대상이면 첫 묶음[0,4)은2레지스터이고 두 번째는6 하나입니다. val_bytes=2이면 첫 raw write는4바이트입니다. flush의 count=(cur-base)/stride이며 마지막은 regtmp+stride를 exclusive 끝으로 넘깁니다. 시작 주소 차이를 바이트 데이터 길이로 그대로 쓰는 것이 아닙니다.
 */
static int regcache_sync_block_raw(struct regmap *map, void *block,
			    unsigned long *cache_present,
			    unsigned int block_base, unsigned int start,
			    unsigned int end)
{
	unsigned int i, val;
	unsigned int regtmp = 0;
	unsigned int base = 0;
