/* 학습 해설
 * Rbtree 초기 할당과 해제: 읽기 허용 구간으로 공간을 예상한다
 * 첫 레지스터를 쓸 때 주변에 어떤 주소가 이어질지 알면 재할당을 줄일 수 있습니다. 하지만 미리 확보한 공간이 실제로 읽은 값이 되는 것은 아니며 초기화 실패 때 이미 만든 노드도 정리해야 합니다.
 * node_alloc은 rd_table의 yes_ranges를 순서대로 검사하여 reg를 포함하는 첫 구간의 base와 칸 수를 사용합니다. 찾지 못하면 요청 주소 한 칸으로 시작합니다. 값 배열과0 비트맵을 따로 할당하며 단계별 실패는 앞서 얻은 메모리를 해제합니다. init은 빈 루트·NULL 최근 노드를 만들고 기본값들을 write로 삽입합니다. 중간 실패는 exit로 이미 만든 전체 트리를 정리합니다.
 * 읽기 허용 구간100..112,stride4에서108만 처음 쓰면4칸을 미리 만들되 존재 비트는 index2만1입니다. 허용 구간이 매우 크면 사전 할당도 커질 수 있습니다. 이 과정은 yes_ranges를 할당 크기 힌트로 사용하며 여기서 no_ranges까지 빼서 조각내지는 않습니다. 실제 접근 허용 판정과 공간 예측을 구별하세요.
 */
regcache_rbtree_node_alloc(struct regmap *map, unsigned int reg)
{
	struct regcache_rbtree_node *rbnode;
	const struct regmap_range *range;
	int i;

	rbnode = kzalloc(sizeof(*rbnode), map->alloc_flags);
	if (!rbnode)
		return NULL;

	/* If there is a read table then use it to guess at an allocation */
	if (map->rd_table) {
		for (i = 0; i < map->rd_table->n_yes_ranges; i++) {
			if (regmap_reg_in_range(reg,
						&map->rd_table->yes_ranges[i]))
				break;
		}

		if (i != map->rd_table->n_yes_ranges) {
			range = &map->rd_table->yes_ranges[i];
			rbnode->blklen = (range->range_max - range->range_min) /
				map->reg_stride	+ 1;
			rbnode->base_reg = range->range_min;
		}
	}

