/* 학습 해설
 * Rbtree Debugfs 통계: 확보한 칸 수가 유효 항목 수는 아니다
 * 캐시 메모리가 왜 큰지 조사하려면 통계의 숫자가 무엇을 세는지 먼저 알아야 합니다. 확보한 배열 칸을 실제 저장된 레지스터 개수라고 읽으면 희소 구간의 낭비를 발견하지 못합니다.
 * CONFIG_DEBUG_FS에서 rbtree 파일을0400 권한으로 만들고 show는 map lock 아래 트리를 순회합니다. 각 구간의 주소와 칸 수를 출력하고 registers에 blklen에 해당하는 수를 더합니다. 존재 비트1의 개수를 세지 않습니다. mem_size는 context+각 node+값 배열+word 단위로 반올림한 비트맵 크기의 합입니다.
 * 64비트 unsigned long,값4바이트를 가정하고65칸 구간에 실제 값 하나만 있으면 registers는65입니다. 값 공간260바이트와 비트맵16바이트에 node/context 크기가 더해집니다. 비트65개는64비트 word2개가 필요하기 때문입니다. 출력 used bytes에는 할당기 내부 관리 공간 등 실제 메모리 소비의 모든 항목이 들어 있는 것은 아닙니다.
 */
static int rbtree_show(struct seq_file *s, void *ignored)
{
	struct regmap *map = s->private;
	struct regcache_rbtree_ctx *rbtree_ctx = map->cache;
	struct regcache_rbtree_node *n;
	struct rb_node *node;
	unsigned int base, top;
	size_t mem_size;
	int nodes = 0;
	int registers = 0;
	int this_registers, average;

	map->lock(map->lock_arg);

	mem_size = sizeof(*rbtree_ctx);

	for (node = rb_first(&rbtree_ctx->root); node != NULL;
	     node = rb_next(node)) {
		n = rb_entry(node, struct regcache_rbtree_node, node);
		mem_size += sizeof(*n);
		mem_size += (n->blklen * map->cache_word_size);
		mem_size += BITS_TO_LONGS(n->blklen) * sizeof(long);

		regcache_rbtree_get_base_top_reg(map, n, &base, &top);
		this_registers = ((top - base) / map->reg_stride) + 1;
		seq_printf(s, "%x-%x (%d)\n", base, top, this_registers);

