/* 학습 해설
 * 파일 초기화 순서: 참조 수를 마지막에1로 만드는 이유
 * 재사용되는 메모리에는 이전 객체의 주소를 보고 접근하려는 독자가 있을 수 있습니다. 새 객체의 준비가 끝나기 전에 참조 수부터 살아 있게 만들면 독자가 아직 준비되지 않은 상태와 마주칠 여지가 커집니다.
 * init_file은 get_cred로 자격 증명을 참조하고 security_file_alloc을 호출합니다. 실패하면 cred 참조를 반환하고 오류를 전달합니다. 성공하면 f_lock,f_pos_lock,flags,OPEN_FMODE를 초기화한 뒤 마지막에 atomic_long_set으로 f_count=1을 설정합니다. 주석은 SLAB_TYPESAFE_BY_RCU 재사용과 fget의 RCU 패턴을 이 순서의 이유로 설명합니다.
 * 새 file의 참조 수1은 할당 결과를 소유한 참조 하나입니다. 나중에 다른 소유자가 참조를 추가해2가 되면 하나를 반환해도1이므로 파괴하지 않습니다. 다만 f_count가 양수라는 사실만으로 오래된 포인터가 여전히 같은 file을 가리킨다고 증명되지는 않습니다. RCU 독자의 참조 획득과 재검증은 호출자 구현까지 함께 확인해야 합니다.
 */
static int init_file(struct file *f, int flags, const struct cred *cred)
{
	int error;

	f->f_cred = get_cred(cred);
	error = security_file_alloc(f);
	if (unlikely(error)) {
		put_cred(f->f_cred);
		return error;
	}

	spin_lock_init(&f->f_lock);
	/*
	 * Note that f_pos_lock is only used for files raising
	 * FMODE_ATOMIC_POS and directories. Other files such as pipes
	 * don't need it and since f_pos_lock is in a union may reuse
	 * the space for other purposes. They are expected to initialize
	 * the respective member when opening the file.
	 */
	mutex_init(&f->f_pos_lock);
	f->f_flags = flags;
	f->f_mode = OPEN_FMODE(flags);
	/* f->f_version: 0 */

	/*
	 * We're SLAB_TYPESAFE_BY_RCU so initialize f_count last. While
	 * fget-rcu pattern users need to be able to handle spurious
	 * refcount bumps we should reinitialize the reused file first.
	 */

