/* 학습 해설
 * File 경로 초기화: 열기 모드와 실제 읽기 기능의 교집합
 * 파일을 읽기 모드로 요청했다는 사실과 그 파일 형식이 읽기 함수를 제공한다는 사실은 다릅니다. 사용 가능한 동작을 표시하려면 요청한 모드와 제공된 callback을 함께 확인해야 합니다.
 * file_init_path는 path를 복사하고 inode,mapping과 writeback·superblock 오류 관찰 기준을 저장합니다. llseek가 있으면 LSEEK,READ 모드이면서 read 또는 read_iter가 있으면 CAN_READ,WRITE 모드이면서 write 또는 write_iter가 있으면 CAN_WRITE를 켭니다. iocb flags,OPENED,f_op를 설정하고 순수 읽기 모드이면 inode의 readcount를 증가시킵니다.
 * READ 모드인데 read와read_iter가 둘 다 없으면 CAN_READ를 켜지 않습니다. read_iter가 있으면 켭니다. READ와WRITE가 모두 켜진 파일은 순수 읽기 조건에 해당하지 않아 여기서 readcount를 증가시키지 않습니다. alloc_file은 current_cred로 빈 파일을 할당하고 성공한 경우에만 이 초기화를 수행합니다.
 */
static void file_init_path(struct file *file, const struct path *path,
			   const struct file_operations *fop)
{
	file->f_path = *path;
	file->f_inode = path->dentry->d_inode;
	file->f_mapping = path->dentry->d_inode->i_mapping;
	file->f_wb_err = filemap_sample_wb_err(file->f_mapping);
	file->f_sb_err = file_sample_sb_err(file);
	if (fop->llseek)
		file->f_mode |= FMODE_LSEEK;
	if ((file->f_mode & FMODE_READ) &&
	     likely(fop->read || fop->read_iter))
		file->f_mode |= FMODE_CAN_READ;
	if ((file->f_mode & FMODE_WRITE) &&
	     likely(fop->write || fop->write_iter))
		file->f_mode |= FMODE_CAN_WRITE;
	file->f_iocb_flags = iocb_flags(file);
	file->f_mode |= FMODE_OPENED;
	file->f_op = fop;
	if ((file->f_mode & (FMODE_READ | FMODE_WRITE)) == FMODE_READ)
		i_readcount_inc(path->dentry->d_inode);
}

