/* 학습 해설
 * Fput 지연 실행: 참조 수0과 자원 정리 완료는 다른 시점이다
 * 마지막 참조를 놓는 위치가 인터럽트 문맥이면 잠들 수 있는 정리를 곧바로 실행할 수 없습니다. 사용자 작업 문맥에서도 최종 해제를 적절한 시점에 맡겨야 하므로 참조 수0이 즉시 모든 자원 반환을 뜻하지 않습니다.
 * fput은 atomic_long_dec_and_test가 참일 때만 마지막 정리를 예약합니다. OPENED도BACKING도 없는 일반 미완성 객체는 즉시 file_free합니다. 그 외 사용자 태스크이고 인터럽트가 아니면 task_work를 설정하고 TWA_RESUME으로 등록합니다. 성공하면 반환하고 실패하거나 커널 스레드·인터럽트 문맥이면 전역 delayed_fput_list에 넣습니다.
 * 참조 수2에서 첫fput은1로 줄고 정리하지 않습니다. 두 번째fput이0으로 만들면 task_work 등록 성공 시에도 release callback은 나중에 수행됩니다. 등록 실패는 이미exit_task_work를 지난 경우 등이 있어 누수를 막으려고 지연 목록으로 이어집니다. llist_add가 빈 목록에 첫 항목을 넣었다고 알릴 때 delayed work를1tick 뒤로 예약합니다.
 */
void fput(struct file *file)
{
	if (atomic_long_dec_and_test(&file->f_count)) {
		struct task_struct *task = current;

		if (unlikely(!(file->f_mode & (FMODE_BACKING | FMODE_OPENED)))) {
			file_free(file);
			return;
		}
		if (likely(!in_interrupt() && !(task->flags & PF_KTHREAD))) {
			init_task_work(&file->f_task_work, ____fput);
			if (!task_work_add(task, &file->f_task_work, TWA_RESUME))
				return;
