/* 학습 해설
 * File 한도 초기값과 Sysctl: 메모리 예산은 정확한 객체 크기 계산이 아니다
 * 메모리가 작은 시스템에 지나치게 많은 파일 객체를 허용하면 다른 용도로 쓸 공간이 줄어듭니다. 초기 한도는 메모리 규모를 참고해 정하지만 실제file·inode·dentry 비용을 매번 정확히 합산하는 장치는 아닙니다.
 * files_maxfiles_init은 totalram_pages와 nr_free_pages 차이의3/2를 memreserve로 잡고 최대total-1로 제한합니다. 남은 페이지 수에 PAGE_SIZE/1024를 곱해10으로 나눈n을 구한 뒤 NR_FILE과 비교해 큰 값을 max_files로 둡니다. 주석의 대략파일당1KiB,메모리10%라는 가정을 코드로 옮긴 정책입니다.
 * total10000페이지,free8000페이지,PAGE_SIZE4096을 가정하면 reserve=(2000*3)/2=3000페이지이고 n=(7000*4)/10=2800입니다. 최종값은2800으로 단정하지 않고 max(2800,NR_FILE)입니다. 정수 나눗셈의 버림과 최소 기본값도 결과에 영향을 줍니다.
 */
void __init files_maxfiles_init(void)
{
	unsigned long n;
	unsigned long nr_pages = totalram_pages();
	unsigned long memreserve = (nr_pages - nr_free_pages()) * 3/2;

	memreserve = min(memreserve, nr_pages - 1);
	n = ((nr_pages - memreserve) * (PAGE_SIZE / 1024)) / 10;

	files_stat.max_files = max_t(unsigned long, n, NR_FILE);
}

