/* 학습 해설
 * Page Counter 한도 변경: 읽기·교환·재읽기로 경쟁을 알아내기
 * 사용량이 줄어든것을보고한도를낮추는순간다른CPU가새페이지를추가할수있습니다. 한 번 읽은사용량만믿고한도를설정하면이미증가한사용량보다낮은한도를성공으로확정할수있습니다.
 * set_max는usage를읽고요청한도보다크면EBUSY입니다. 그렇지않으면xchg로새max를설치하고usage를다시읽습니다. 재읽은값이처음usage이하이거나새한도가이전한도이상이면성공합니다. 감소중usage가늘었다면이전max를복원하고cond_resched후반복합니다. 같은counter의setter호출은호출자가직렬화해야합니다.
 * 처음usage40,이전max100,요청max50이라고합시다. 교환뒤usage45이면요청한도50이내라도이코드는증가를보았으므로100을복원하고재시도합니다. 다음읽기가45로안정되면50설정을성공할수있습니다. 재시도시usage55면EBUSY입니다. 한도를100에서120으로올리는경우는증가경쟁을보아도그분기에서성공합니다.
 */
int page_counter_set_max(struct page_counter *counter, unsigned long nr_pages)
{
	for (;;) {
		unsigned long old;
		long usage;

		/*
		 * Update the limit while making sure that it's not
		 * below the concurrently-changing counter value.
		 *
		 * The xchg implies two full memory barriers before
		 * and after, so the read-swap-read is ordered and
		 * ensures coherency with page_counter_try_charge():
		 * that function modifies the count before checking
		 * the limit, so if it sees the old limit, we see the
		 * modified counter and retry.
		 */
		usage = page_counter_read(counter);

		if (usage > nr_pages)
			return -EBUSY;

		old = xchg(&counter->max, nr_pages);

		if (page_counter_read(counter) <= usage || nr_pages >= old)
			return 0;

