/* 학습 해설
 * 보호 사용량 전파: 선언한100페이지와 실제쓰는30페이지의 차이
 * 자식이보호량100을선언해도실제로30페이지만쓰면현재보호에필요한양은30입니다. 선언값을그대로합산하면쓰지도않는몫이다른자식의보호예산을막을수있습니다.
 * 부모가있을때min(usage,min)을새min_usage로삼고이전값과다르면atomic_long_xchg합니다. 교환이반환한실제이전값과의차이를부모children_min_usage에더합니다. low도같은절차입니다. 부모가없으면돌아갑니다. set_min과set_low는설정값을WRITE_ONCE한뒤해당counter부터조상까지현재usage로전파를재계산합니다.
 * 자식설정min100,usage30이면보호사용량30입니다. usage가50으로오르면부모의자식보호합계에는20을더합니다. 설정min을20으로낮추면자식보호량50→20,부모합계에는-30을반영합니다. 부모의설정값을바꾸거나메모리30페이지를해제하는동작은아닙니다.
 */
static void propagate_protected_usage(struct page_counter *c,
				      unsigned long usage)
{
	unsigned long protected, old_protected;
	long delta;

	if (!c->parent)
		return;

	protected = min(usage, READ_ONCE(c->min));
	old_protected = atomic_long_read(&c->min_usage);
	if (protected != old_protected) {
		old_protected = atomic_long_xchg(&c->min_usage, protected);
		delta = protected - old_protected;
		if (delta)
			atomic_long_add(delta, &c->parent->children_min_usage);
	}

	protected = min(usage, READ_ONCE(c->low));
	old_protected = atomic_long_read(&c->low_usage);
	if (protected != old_protected) {
		old_protected = atomic_long_xchg(&c->low_usage, protected);
		delta = protected - old_protected;
		if (delta)
			atomic_long_add(delta, &c->parent->children_low_usage);
	}

