/* 학습 해설
 * 재귀 보호의 남는 예산: 이미 보호한 페이지를 두 번 세지 않는다
 * 자식마다보호량을세밀하게설정하지않아도하위트리전체를이웃트리로부터보호하고싶을수있습니다. 부모의남는예산을추가배분할때는이미보호받은사용량을제외해야중복혜택을줄입니다.
 * 재귀옵션이켜지고parent_effective>siblings_protected,parent_usage>siblings_protected,usage>protected일때남는예산에(usage-protected)/(parent_usage-siblings_protected)를곱해ep에더합니다. calculate_protection은root자체와usage0에서는갱신하지않습니다. 부모가root이면설정min/low를직접emin/elow에넣고그아래에서는이함수로각각계산합니다.
 * 부모예산100,형제보호합40,부모사용160,내사용80,내보호20이면남는예산60중60*(80-20)/(160-40)=30을추가해유효보호50입니다. 가중치80을그대로쓰면이미보호한20도다시배분대상이됩니다. 부모사용이보호합과같으면분모0이므로추가배분조건에서제외합니다.
 */
void page_counter_calculate_protection(struct page_counter *root,
				       struct page_counter *counter,
				       bool recursive_protection)
{
	unsigned long usage, parent_usage;
	struct page_counter *parent = counter->parent;

	/*
	 * Effective values of the reclaim targets are ignored so they
	 * can be stale. Have a look at mem_cgroup_protection for more
	 * details.
	 * TODO: calculation should be more robust so that we do not need
	 * that special casing.
	 */
	if (root == counter)
		return;

	usage = page_counter_read(counter);
	if (!usage)
		return;

	if (parent == root) {
		counter->emin = READ_ONCE(counter->min);
		counter->elow = READ_ONCE(counter->low);
		return;
	}

