/* 학습 해설
 * Task Work 큐: compare-and-exchange로 맨 앞에 작업을 붙인다
 * 다른 실행 문맥에서 특정 태스크가 나중에 수행할 정리를 등록할 때,동시에 여러 등록이 들어와도 작업을 잃지 않아야 합니다. 단순히 head를읽고새노드를대입하면중간에다른CPU가넣은작업을덮어쓸수있습니다.
 * add는task_works를READ_ONCE로읽고work->next=head를설정한뒤try_cmpxchg로head가그대로일때만새work로바꿉니다. 비교실패시head가관찰된현재값으로갱신되므로next를다시연결해재시도합니다. head가work_exited sentinel이면ESRCH로거부합니다. 새작업을맨앞에놓으므로기본연결형태는LIFO입니다.
 * 처음A가있을때CPU1은B→A를준비하고CPU2는C를먼저넣어C→A를만들었다고합시다. CPU1의A비교는실패하고B→C로next를바꾼뒤성공하면B→C→A가됩니다. 다시시도하지않고B를대입했다면C를잃었을것입니다. 순서가중요한사용자는동시등록과실행분리를포함한별도계약이필요하며원문도작업순서보장을제공하지않는다고명시합니다.
 */
int task_work_add(struct task_struct *task, struct callback_head *work,
		  enum task_work_notify_mode notify)
{
	struct callback_head *head;
	int flags = notify & TWA_FLAGS;

	notify &= ~TWA_FLAGS;
	if (notify == TWA_NMI_CURRENT) {
		if (WARN_ON_ONCE(task != current))
			return -EINVAL;
		if (!IS_ENABLED(CONFIG_IRQ_WORK))
			return -EINVAL;
	} else {
		/*
		 * Record the work call stack in order to print it in KASAN
		 * reports.
		 *
		 * Note that stack allocation can fail if TWAF_NO_ALLOC flag
		 * is set and new page is needed to expand the stack buffer.
		 */
		if (flags & TWAF_NO_ALLOC)
			kasan_record_aux_stack_noalloc(work);
		else
			kasan_record_aux_stack(work);
	}

