/* 학습 해설
 * Task Work 취소: 함수가 같은 작업과 객체가 같은 작업은 다르다
 * 같은callback함수를사용하는작업여러개가서로다른파일을정리할수있습니다. 함수이름으로하나를취소할지특정작업객체만취소할지구별하지않으면다른자원의정리를없앨수있습니다.
 * cancel_match는pending이없으면NULL입니다. pi_lock을IRQ저장과함께잡고목록을pprev라는이전연결의주소로순회합니다. match가거짓이면다음연결로이동하고참이면try_cmpxchg로그연결을work->next로바꿉니다. 실패시pprev를옮기지않고재검사합니다. cancel_func는func동일성을,cancel은callback객체주소동일성을사용합니다.
 * 최근등록B→이전등록A이고둘의func가F라면cancel_func(F)는먼저만난B를제거해A를남깁니다. cancel(A)는B를건너A객체만제거합니다. 취소함수는찾은작업또는성공여부를반환하며callback을실행하거나객체를free하지않습니다. 반환된작업의소유권정리는호출자가해야합니다.
 */
task_work_cancel_match(struct task_struct *task,
		       bool (*match)(struct callback_head *, void *data),
		       void *data)
{
	struct callback_head **pprev = &task->task_works;
	struct callback_head *work;
	unsigned long flags;

	if (likely(!task_work_pending(task)))
		return NULL;
	/*
	 * If cmpxchg() fails we continue without updating pprev.
	 * Either we raced with task_work_add() which added the
	 * new entry before this work, we will find it again. Or
	 * we raced with task_work_run(), *pprev == NULL/exited.
	 */
	raw_spin_lock_irqsave(&task->pi_lock, flags);
	work = READ_ONCE(*pprev);
	while (work) {
		if (!match(work, data)) {
			pprev = &work->next;
			work = READ_ONCE(*pprev);
		} else if (try_cmpxchg(pprev, &work, work->next))
			break;
	}
	raw_spin_unlock_irqrestore(&task->pi_lock, flags);

