/* 학습 해설
 * Task Work 실행: 목록을 떼어낸 뒤 callback이 새 작업을 넣으면
 * callback을실행하는동안다른작업이등록되거나callback자신이작업을추가할수있습니다. 실행할목록과새등록목록을분리하면작업을실행하는내내등록을막는큰잠금이필요없습니다.
 * run은current의task_works를try_cmpxchg로NULL과교환해현재목록을떼어냅니다. pi_lock을잡았다풀어취소자와동기화한뒤각노드의next를먼저저장하고func를호출합니다. 각callback뒤cond_resched하며떼어낸목록이끝나면바깥루프로돌아새등록목록을다시확인합니다.
 * 떼어낸목록B→A를처리하면서B가C를등록하면C는task의새목록에들어갑니다. 현재배치에서는B다음A를처리하고바깥반복에서C를가져옵니다. next를callback전에저장하는이유는callback이자기객체를정리할수있어실행후그객체의next를다시읽으면수명이끝난메모리에접근할수있기때문입니다.
 */
void task_work_run(void)
{
	struct task_struct *task = current;
	struct callback_head *work, *head, *next;

	for (;;) {
		/*
		 * work->func() can do task_work_add(), do not set
		 * work_exited unless the list is empty.
		 */
		work = READ_ONCE(task->task_works);
		do {
			head = NULL;
			if (!work) {
				if (task->flags & PF_EXITING)
					head = &work_exited;
				else
					break;
			}
		} while (!try_cmpxchg(&task->task_works, &work, head));

		if (!work)
			break;
		/*
		 * Synchronize with task_work_cancel_match(). It can not remove
		 * the first entry == work, cmpxchg(task_works) must fail.
		 * But it can remove another entry from the ->next list.
		 */

